<?php

declare(strict_types=1);

namespace PhpWing\Model;

use PhpWing\Enum\IntegrationType;

/**
 * Payment to authorize. `rand_str` and `timestamp` are generated by the SDK;
 * every optional field is sent only when set.
 */
final readonly class Payment
{
    /**
     * @param string $orderReferenceNo your unique order id (`order_reference_no`)
     * @param int|float $amount amount to pay, at most 2 decimals; sent as `15.00`
     * @param string $returnUrl Wing redirects the payer here (GET) after paying, with `?status=success&token=...`
     * @param string $cancelUrl Wing redirects the payer here (GET) when they cancel
     * @param IntegrationType $integrationType WebApp (default) or MobileApp for the deep link back to your app
     * @param bool $isWingAppInstalled whether the Wing Bank app is on the payer's phone (`is_wingapp_installed`)
     * @param ?string $itemName remark of the product or item, max 255 characters
     * @param ?string $merchantName name shown to the payer; Wing shows your registered name without it
     * @param ?string $wingAccount Wing account filled in for the payer
     */
    public function __construct(
        public string $orderReferenceNo,
        public int|float $amount,
        public string $returnUrl,
        public string $cancelUrl,
        public IntegrationType $integrationType = IntegrationType::WebApp,
        public bool $isWingAppInstalled = false,
        public ?string $itemName = null,
        public ?string $merchantName = null,
        public ?string $wingAccount = null,
    ) {}
}
